export interface SpeakerOptions {
  sampleRate?: number
  channels?: number
  bitDepth?: 8 | 16 | 24 | 32
  bufferSize?: number
  backend?: 'miniaudio' | 'process' | 'null'
  /** an output by its id or name (from devices()), else the one whose name holds it (any case); none: the default */
  device?: string
}

export interface Device {
  /** the platform's own: CoreAudio's UID, WASAPI's endpoint id, ALSA's or PulseAudio's name */
  id: string
  name: string
  default: boolean
}

/** The outputs */
export function devices(opts?: { backend?: 'miniaudio' | 'process' | 'null' }): Promise<Device[]>
/** A device's id by its id or name, else the one whose name holds `device` (any case) when only one does */
export function pick(all: Device[], device?: string): string | undefined

export interface WriteFn {
  (chunk: Buffer | Uint8Array | AudioBuffer | null, cb?: (err: Error | null, frames?: number) => void): void
  end(): void
  flush(cb?: () => void): void
  close(): void
  backend: string
}

declare function speaker(opts?: SpeakerOptions): WriteFn

declare namespace speaker {
  /** Consume an async iterable of PCM chunks through the speaker. */
  function from(source: AsyncIterable<Buffer | Uint8Array | AudioBuffer>, opts?: SpeakerOptions): Promise<void>
}

export default speaker
